import {createBrowserTools,validateBrowserConfig,prepareMedia,publicConfig} from './lib/browser-providers.mjs';
import {connectionForm,bindConnectionForm,DEFAULT_BROWSER_CONFIG} from './connect.mjs';
import {AGENTS,Engine,createRun,clone,validateArtifact} from './lib/engine.mjs';
import {DEFAULT_BRIEF,demoTools,completedDemo} from './lib/demo.mjs';
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',film:'M4 3h16v18H4z M4 8h16 M4 16h16 M8 3v18 M16 3v18',folder:'M3 7V4h6l2 3h10v13H3z',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',brain:'M9 4C4 1 1 8 5 10c-5 3-1 10 3 8 2 5 4 2 4-1V6c0-3-3-4-3-2z M15 4c5-3 8 4 4 6 5 3 1 10-3 8-2 5-4 2-4-1',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3z M12 6v16',settings:'M9 3h6l1 4 4 1 2 4-3 3 1 4-5 2-3-3-4 2-4-4 2-4-3-3 2-5 4 1z M9 12a3 3 0 1 0 6 0 3 3 0 1 0-6 0',plus:'M12 5v14 M5 12h14',chev:'m8 5 7 7-7 7',down:'m6 9 6 6 6-6',play:'m8 4 13 8-13 8z',pause:'M8 5v14 M16 5v14',stop:'M6 6h12v12H6z',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',edit:'m4 16 12-12 4 4L8 20H4z M13 7l4 4',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 0-20 0 10 10 0 1 0 20 0',mic:'M9 3h6v10a3 3 0 0 1-6 0z M5 11v2a7 7 0 0 0 14 0v-2 M12 20v3 M8 23h8',image:'M3 3h18v18H3z m0 14 5-5 5 5 3-3 5 5 M16 7h.01',file:'M5 2h10l4 4v16H5z M14 2v6h5 M8 12h8 M8 16h8',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h.01 M3 12h.01 M3 18h.01',close:'m6 6 12 12 M18 6 6 18',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 0-20 0 10 10 0 1 0 20 0',refresh:'M20 7a9 9 0 1 0 1 8 M20 2v6h-6',link:'m9 15 6-6 M7 14l-2 2a4 4 0 0 0 5 5l4-4 M10 7l4-4a4 4 0 0 1 6 6l-2 2',menu:'M4 6h16 M4 12h16 M4 18h16',volume:'M3 9h4l5-5v16l-5-5H3z M16 8a6 6 0 0 1 0 8 M19 5a10 10 0 0 1 0 14',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z m-5 10 3 3 5-6'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const SOURCE='FrameFlow · 开源 Agent 工作台';
const browserMediaURLs=new Set();
let browserConfig={...DEFAULT_BROWSER_CONFIG,...publicConfig({...DEFAULT_BROWSER_CONFIG,...read('frameflow-api-config',{})})};
let projects=[],currentId='',view='overview',engine=null,remoteTimer=null,playing=false,playTime=0,playTimer=null,narrationOn=false,lastShot=-1;
let settings={mode:'demo',endpoint:'',...read('frameflow-settings',{})};
if(new URLSearchParams(location.search).get('mode')==='demo')settings.mode='demo';
if(location.hash==='#connect')settings.mode='browser';
function read(k,f){try{return JSON.parse(localStorage.getItem(k))??f;}catch{return f;}}
function save(){try{localStorage.setItem('frameflow-projects',JSON.stringify(projects));localStorage.setItem('frameflow-current',currentId);}catch{toast('本地存储空间不足，请导出备份');}}
function toast(s){const el=document.createElement('div');el.className='toast';el.textContent=s;document.querySelector('#toasts').append(el);setTimeout(()=>el.remove(),4500);}
function sample(){const r=createRun(DEFAULT_BRIEF);const x=completedDemo();r.artifacts={...x.artifacts,plan:{summary:'样例计划：从故事到短剧的完整创作流程',tasks:['创意拆解','三幕剧本','分镜设计','影像与配音','音画合成']},review:{passed:true,findings:['示例规则审查通过']},video:{clips:x.artifacts.storyboard.shots.map(s=>({shotId:s.id,url:`demo://${s.id}`,duration:s.duration}))},voice:{url:'demo://browser-speech',transcript:x.artifacts.storyboard.shots.map(s=>s.narration).join('。')},compose:{url:'demo://preview',format:'动态分镜预览'}};r.status='completed';r.approved=true;r.isSample=true;for(const n of Object.values(r.nodes))n.status='completed';r.memory={characters:x.artifacts.script.characters,style:DEFAULT_BRIEF.style,facts:[x.artifacts.script.logline],summaries:[{node:'script',summary:'已加载预制示例；点击重新运行可查看实时编排',time:r.createdAt}]};r.events=[{time:r.createdAt,type:'sample',node:null,message:'已加载预制演示项目；未调用外部模型'}];return r;}
projects=read('frameflow-projects',[]).filter(p=>p?.id&&p.nodes&&p.brief);
if(!projects.length)projects=[sample()];currentId=read('frameflow-current',projects[0].id);if(!projects.some(p=>p.id===currentId))currentId=projects[0].id;
for(const p of projects)if(p.status==='running'&&p.mode==='demo'){p.status='cancelled';for(const n of Object.values(p.nodes))if(n.status==='running')n.status='pending';}
// Browser audio and composed videos use session-only Blob URLs. Keep durable text/video jobs,
// and invalidate the media that cannot survive a browser restart.
for(const p of projects)if(p.mode==='browser'){
  const ephemeral=p.artifacts.voice||p.artifacts.compose||p.status==='running';
  delete p.artifacts.voice;delete p.artifacts.compose;
  for(const id of ['voice','compose'])p.nodes[id]={status:'pending',attempts:0};
  for(const node of Object.values(p.nodes))if(node.status==='running')node.status='pending';
  if(ephemeral){p.status='cancelled';p.events.push({time:new Date().toISOString(),type:'session',node:null,message:'已保留文字产物与视频任务；请重新填写 API Key 后生成本页音轨与成片。'});}
}
const current=()=>projects.find(p=>p.id===currentId)||projects[0];
const active=()=>current().status==='running';
const states={pending:'等待中',running:'执行中',completed:'已完成',failed:'失败',cancelled:'已停止',idle:'待运行',awaiting_review:'待确认'};
const agentIcon={plan:'brain',script:'file',review:'shield',storyboard:'image',video:'film',voice:'mic',compose:'spark'};
const totals=()=>{const r=current();return {done:Object.values(r.nodes).filter(n=>n.status==='completed').length,shots:r.artifacts.storyboard?.shots||[],duration:r.artifacts.storyboard?.shots.reduce((n,s)=>n+s.duration,0)||r.brief.duration};};
function sidebar(){return `<aside class="sidebar"><a class="brand" href="./" aria-label="返回公开 Agent 架构首页"><b class="brandmark">F</b>Frame<span>flow</span></a><button class="workspace-switch" data-action="projects"><span class="workspace-icon">${icon('film')}</span><span>创意工作空间<br><span class="muted small">仅存本机浏览器</span></span>${icon('down','chev')}</button><p class="navlabel">WORKSPACE</p>${[['overview','grid','创作工作台'],['projects','folder','我的项目'],['assets','image','素材与产物'],['agents','brain','Agent 编排'],['memory','book','项目记忆']].map(([id,i,name])=>`<button class="navbutton ${view===id||id==='overview'&&['script','storyboard','preview'].includes(view)?'active':''}" data-view="${id}">${icon(i)}${name}${id==='agents'?'<span class="tag">7</span>':''}</button>`).join('')}<div class="projectnav"><p class="navlabel">RECENT PROJECTS</p>${projects.slice(0,4).map(p=>`<button class="project-link ${p.id===currentId?'active':''}" data-project="${p.id}"><i class="project-dot" style="background:${p.mode==='live'?'#91bbab':'#b6a0ed'}"></i><span>${esc((p.brief.title||'未命名项目').slice(0,11))}</span></button>`).join('')}<button class="project-link" data-action="new">${icon('plus')}新建短剧</button></div><div class="sidebar-bottom"><div class="sidebar-note"><div class="flex">${icon('spark')}<span style="font-size:12px">让灵感，进入下一帧。</span></div><p>从一个故事，到一部短剧<br>与 AI 创作团队一起完成</p><button data-action="docs">了解项目设计 ${icon('book')}</button></div><button class="navbutton" data-action="settings">${icon('settings')}模型与连接</button><div class="user"><span class="avatar">FF</span><div><strong>无需登录</strong><div class="muted">本地创作项目</div></div></div></div></aside>`;}
function render(){const r=current(),t=totals();app.innerHTML=`<div class="layout">${sidebar()}<div class="content"><header class="topbar"><div class="breadcrumb"><button class="iconbtn mobile-nav" aria-label="导航菜单" data-action="menu">${icon('menu')}</button><span class="root-crumb">工作空间</span><span class="root-crumb">/</span><span>短剧项目</span><span>/</span><span>${esc(r.brief.title)}</span></div><div class="top-actions"><button class="badge ${r.mode==='live'?'green':''}" data-action="settings">${icon('spark')}${r.mode==='demo'?'演示模式':'真实接口'}</button><button class="iconbtn" aria-label="项目设计说明" data-action="docs">${icon('info')}</button><button class="iconbtn" aria-label="模型与连接设置" data-action="settings">${icon('settings')}</button></div></header><div class="body-grid"><main id="main" tabindex="-1"><div class="heading"><div><div class="project-title-line"><h1>${view==='projects'?'我的项目':view==='agents'?'Agent 编排':view==='memory'?'项目记忆':view==='assets'?'素材与产物':esc(r.brief.title)}</h1><span class="badge ${r.status==='completed'?'green':r.status==='awaiting_review'?'amber':''}">${r.isSample?'示例项目':states[r.status]}</span></div><p>${view==='agents'?'让每一位创作 Agent，各司其职。':view==='memory'?'将角色、风格和创作事实，带入每一轮生成。':'从故事灵感到视听作品，让创作自然发生。'}</p></div><div class="buttons"><button class="btn" data-action="export">${icon('download')}导出项目</button><button class="btn primary" data-action="${active()?'stop':r.status==='awaiting_review'?'approve':'run'}">${icon(active()?'stop':r.status==='awaiting_review'?'check':'spark')}${active()?'停止执行':r.status==='awaiting_review'?'确认并继续':r.status==='completed'?'重新运行':['failed','cancelled'].includes(r.status)?'继续执行':'运行工作流'}</button></div></div>${['overview','script','storyboard','preview'].includes(view)?`<div class="tabs">${[['overview','grid','创作概览'],['script','file','剧本编辑'],['storyboard','image','分镜脚本'],['preview','film','成片预览']].map(([v,i,n])=>`<button class="tab ${v===view?'active':''}" data-view="${v}">${icon(i)}${n}</button>`).join('')}</div>`:''}${r.status==='failed'?`<div class="alert">${icon('info')} ${esc(r.events.at(-1)?.message)}<br>已完成产物已保留。修正连接或工具配置后，可继续执行。</div>`:''}<div id="view-content">${content()}</div></main>${rightbar()}</div><footer class="statusbar"><span><i class="status-dot"></i>本地自动保存 · ${new Date(r.updatedAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</span><span>LLM / MLLM · Multi-Agent Orchestration</span><a href="https://github.com/WanyueZhang-ai/frameflow-ai-drama" target="_blank" rel="noopener noreferrer" aria-label="在新标签页查看 GitHub 开源项目">GitHub · MIT 开源</a></footer></div></div>`;if(view==='preview')updatePlayer();}
function content(){return ({overview,script:scriptView,storyboard:boardView,preview:previewView,agents:agentsView,memory:memoryView,assets:assetsView,projects:projectsView,logs:logsView})[view]?.()||overview();}
function overview(){const r=current(),a=r.artifacts,t=totals();return `<div class="hero"><img src="assets/rain-store.webp" alt="AI 概念图：雨夜中透出暖光的便利店与撑伞女孩"><span class="hero-meta">A FRAMEFLOW ORIGINAL · CONCEPT</span><div class="hero-copy"><div class="eyebrow">YOUR NEXT STORY STARTS HERE</div><h2>每一个灵感<br>都值得被看见。</h2><p>把故事交给你的 AI 创作团队，<br>让文字、画面与声音在此相遇。</p><div class="hero-footer"><span class="hero-chip">${esc(r.brief.genre)}</span><span class="hero-chip">${r.brief.duration} SEC</span><span class="hero-chip">${esc(r.brief.ratio)}</span></div></div><button class="hero-play" aria-label="打开成片预览" data-view="preview">${icon('play')}</button></div><div class="sectiontitle"><h2>创作简报</h2><span class="caption">CREATIVE BRIEF</span></div><div class="brief-card"><div class="brief-label">${icon('spark')}故事的起点</div><p class="brief-text">${esc(r.brief.idea)}</p><div class="brief-footer"><span class="chip">${esc(r.brief.genre)}</span><span class="chip">${esc(r.brief.style)}</span><span class="chip">${r.brief.duration} 秒</span><span class="chip">${esc(r.brief.ratio)}</span><span class="chip">${r.brief.manualReview?'人工确认分镜':'自动执行'}</span><button class="edit" data-action="editbrief" ${active()?'disabled':''}>${icon('edit')} 编辑简报</button></div></div><div class="sectiontitle"><h2>创作流水线</h2><button class="btn ghost sm" data-view="agents">查看编排 ${icon('grid')}</button></div><div class="flow-cards">${[['script','file','剧本生成',a.script?`${a.script.scenes.length} 个场景 · ${a.script.characters.length} 位角色`:'等待故事成形'],['storyboard','image','分镜脚本',a.storyboard?`${t.shots.length} 个镜头 · ${t.duration} 秒`:'镜头与视觉提示词'],['preview','film','视频生成',a.video?`${a.video.clips.length} 段${r.mode==='demo'?'演示镜头':'视频素材'}`:'镜头级影像生成'],['preview','mic','配音合成',a.voice?(r.mode==='demo'?'浏览器语音演示':'音轨已生成'):'音色、对白与字幕']].map(([v,i,title,desc],index)=>`<button class="flow-card" data-view="${v}"><span class="flow-icon">${icon(i)}</span>${a[['script','storyboard','video','voice'][index]]?`<span class="done">${icon('check')}</span>`:''}<h3>${title}</h3><p>${desc}</p></button>`).join('')}</div><p class="footnote">${icon('info')}<span>${r.mode==='demo'?'当前为可交互演示：剧本使用规则模板，画面为 AI 概念图，视频为动态分镜，配音使用浏览器朗读。':'当前使用真实接口：密钥由服务端环境变量管理，执行产物来自配置的模型与媒体工具。'}</span></p>`;}
function empty(label){return `<div class="empty">${icon('spark')}<h3>${label}还在等待灵感</h3><p>填写创作简报并运行工作流，Agent 会在这里交付产物。</p><button class="btn primary" data-action="run" ${active()?'disabled':''}>${icon('play')}开始创作</button></div>`;}
function scriptView(){const a=current().artifacts.script;if(!a)return empty('剧本');return `<div class="panel"><div class="panel-head"><div><h2>${esc(a.title)}</h2><p>三幕叙事 · ${a.scenes.length} 个场景</p></div><button class="btn sm" data-action="editscript" ${active()?'disabled':''}>${icon('edit')}编辑剧本</button></div><div class="character-row">${a.characters.map(c=>`<div class="character"><span class="avatar">${esc(c.name.slice(0,1))}</span><div><strong>${esc(c.name)}</strong><p>${esc(c.description)}</p></div></div>`).join('')}</div><p class="script-logline">${esc(a.logline)}</p>${a.scenes.map((s,i)=>`<section class="scene"><h3 class="scene-location">${String(i+1).padStart(2,'0')} / ${esc(s.location)}</h3><p class="scene-beat">${esc(s.beat)}</p>${s.dialogue.map(d=>`<div class="dialogue"><strong>${esc(d.speaker)}</strong><span>“${esc(d.text)}”</span></div>`).join('')}</section>`).join('')}</div><p class="footnote">${icon('brain')}角色设定将写入项目记忆，在分镜与视频生成中持续复用。</p>`;}
function boardView(){const a=current().artifacts.storyboard;if(!a)return empty('分镜');return `<div class="sectiontitle"><h2>镜头序列 <span class="muted small">/ ${a.shots.length} SHOTS</span></h2><button class="btn sm" data-action="exportboard">${icon('download')}导出分镜</button></div><div class="info-strip">${icon('image')} ${current().mode==='demo'?'各镜头共用概念图裁切，用于演示分镜；文字提示词可编辑。':'分镜继承角色记忆，可编辑视觉提示词后再提交生成。'}</div><div class="shot-grid">${a.shots.map((s,i)=>`<button class="shot" data-shot="${i}"><div class="shot-img shot${i%6+1}"><img src="assets/rain-store.webp" alt="${esc(s.visual)}"><span class="shot-num">SHOT ${String(i+1).padStart(2,'0')}</span><span class="shot-dur">${s.duration.toFixed(1)}s</span></div><div class="shot-content"><h3>${esc(s.camera)}</h3><p>${esc(s.visual)}</p><div class="shot-metadata">${esc(s.sceneId)} · ${esc(current().brief.ratio)} · 编辑提示词</div></div></button>`).join('')}</div>`;}
function previewView(){const r=current(),a=r.artifacts;if(!a.compose)return empty('成片');if(r.mode!=='demo')return `<div class="panel"><video class="live-video" src="${esc(safeMedia(a.compose.url))}" controls preload="metadata"></video><p class="result-note">${r.mode==='browser'?'自带 API · 浏览器合成':'个人服务端合成'} · ${esc(a.compose.format)}</p><button class="btn primary" data-action="downloadvideo">${icon('download')}下载成片</button></div>`;return `<div class="info-strip">${icon('info')} 动态分镜演示 · 概念图运镜与字幕，不是视频模型生成的成片</div><div class="preview-stage ${r.brief.ratio==='9:16'?'portrait':''}" id="player"><img id="player-image" src="assets/rain-store.webp" alt="动态分镜演示画面"><div class="frame-label">FRAMEFLOW · CONCEPT FILM</div><div class="subtitles" id="subtitle"></div><button class="centerplay" id="centerplay" data-action="play" aria-label="播放预览">${icon('play')}</button></div><div class="preview-controls"><button class="iconbtn" id="playbutton" data-action="play" aria-label="播放或暂停">${icon(playing?'pause':'play')}</button><span class="time" id="playtime">00:00 / 01:00</span><input id="seek" type="range" min="0" max="${totals().duration}" value="${playTime}" step="0.1" aria-label="播放进度"><button class="btn sm" data-action="narration">${icon('volume')}<span id="voice-label">${narrationOn?'朗读已开':'开启朗读'}</span></button></div><div class="timeline">${a.storyboard.shots.map((s,i)=>`<button data-seek="${i}" aria-label="跳转镜头 ${i+1}"><img src="assets/rain-store.webp" alt=""><span>SHOT ${String(i+1).padStart(2,'0')}</span></button>`).join('')}</div><div class="audio-track">${icon('mic')}AI 声音轨道 · 浏览器语音预览<small>系统中文音色 · 实时朗读</small></div><p class="result-note">演示可播放镜头与字幕，并通过系统音色朗读。视频文件导出需要切换真实接口，接入视频生成、TTS 与 FFmpeg 合成工具。</p><div class="download-grid"><button class="btn" data-action="exportsrt">${icon('download')}导出字幕 SRT</button><button class="btn" data-action="exportscript">${icon('file')}导出剧本</button><button class="btn" data-action="export">${icon('folder')}完整项目 JSON</button></div>`;}
function rightbar(){const r=current(),t=totals();return `<aside class="rightbar" aria-label="Agent 执行面板"><div class="right-title"><h2>创作团队</h2><span class="badge" style="font-size:9px;padding:2px 6px">${active()?'协作中':'7 AGENTS'}</span></div><p class="intro">专注创意，交给专业的 AI 伙伴。</p>${r.status==='awaiting_review'?`<div class="run-notice">导演已交付分镜。确认镜头与提示词后，继续生成影像与声音。<button class="btn primary sm" data-view="storyboard">查看分镜</button><button class="btn sm" data-action="approve">${icon('check')}确认并继续</button></div>`:''}<div class="progress-head"><span>工作流进度</span><strong>${t.done} / 7</strong></div><div class="progress-track"><div style="width:${t.done/7*100}%"></div></div><div class="agent-list">${AGENTS.map(a=>{const n=r.nodes[a.id];return `<div class="agent" style="--agent-color:${a.color}"><span class="agent-avatar">${icon(agentIcon[a.id])}</span><div class="agent-info"><div class="agent-top"><strong>${a.name}</strong><span class="agent-status ${n.status}">${n.status==='running'?'<i class="spinner"></i>':n.status==='completed'?icon('check'):''}${states[n.status]}</span></div><div class="agent-desc">${a.role}${n.elapsed?` · ${(n.elapsed/1000).toFixed(1)}s`:''}</div><div class="agent-tool">${a.tool}</div></div></div>`;}).join('')}</div><hr class="right-divider"><div class="log-title"><span>执行记录</span><button data-view="logs">全部记录</button></div><div class="logbox">${r.events.slice(-5).reverse().map(e=>`<div class="log-row"><span class="log-time">${new Date(e.time).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</span><span class="log-text">${e.node?`<span class="log-agent">${esc(AGENTS.find(a=>a.id===e.node)?.name)}<br></span>`:''}${esc(e.message)}</span></div>`).join('')||'<p class="muted small">运行后将在这里记录工具调用。</p>'}</div><hr class="right-divider"><button class="btn sm" style="width:100%" data-view="memory">${icon('brain')}查看项目记忆</button></aside>`;}
function agentsView(){return `<div class="architecture"><div>创作简报 + 项目记忆</div><div>制片规划 › 剧本生成 › 一致性审查 › 分镜设计</div><div><span class="badge amber">人工确认</span>　视频生成 ∥ 配音合成　›　音画合成</div></div><div class="sectiontitle"><h2>职责与工具注册表</h2><span class="caption">DEPENDENCY GRAPH</span></div><div class="agent-grid">${AGENTS.map(a=>`<div class="agent-card"><div class="card-top"><span class="agent-avatar" style="--agent-color:${a.color}">${icon(agentIcon[a.id])}</span><div><h3>${a.name}</h3><span class="muted small">${a.role}</span></div></div><p>${{plan:'将创作简报拆成可执行任务，确定时长、画幅与依赖。',script:'输出角色、场景、对白和叙事结构，将角色事实写入记忆。',review:'审查角色引用与叙事连贯性；真实模式使用独立模型审稿。',storyboard:'将剧本转为镜头序列，复用角色设定；可读参考图进行多模态规划。',video:'通过视频适配器提交镜头任务，轮询结果并记录外部任务 ID。',voice:'读取镜头旁白，调用 TTS 工具生成音轨，交付配音和字幕。',compose:'使用 FFmpeg 将镜头、音轨和字幕时间线合成可下载文件。'}[a.id]}</p><code>${a.tool}</code><p style="margin-top:7px">依赖：${a.deps.length?a.deps.map(d=>AGENTS.find(x=>x.id===d).role).join(' + '):'创作简报'}</p></div>`).join('')}</div><div class="panel mt"><h3>运行机制</h3><table class="data-table"><tbody><tr><th>任务状态</th><td>等待、执行、完成、失败；人工确认、停止与恢复</td></tr><tr><th>工具调用</th><td>输入约束、结构校验、瞬时错误指数退避重试</td></tr><tr><th>并行执行</th><td>视频与配音使用独立任务，二者完成后才进入合成</td></tr><tr><th>记忆机制</th><td>角色事实、风格约束、任务摘要、执行检查点</td></tr><tr><th>可追溯性</th><td>每次调用、重试、耗时与产物均可查看、导出</td></tr></tbody></table></div>`;}
function memoryView(){const m=current().memory;return `<div class="panel"><div class="panel-head"><div><h2>让故事始终如一</h2><p>项目级结构化记忆，在每个 Agent 之间传递。</p></div><span class="badge">PROJECT MEMORY</span></div><div class="stats"><div><strong>${m.characters.length}</strong>角色设定</div><div><strong>${m.facts.length}</strong>故事事实</div><div><strong>${m.summaries.length}</strong>任务摘要</div></div></div><div class="sectiontitle"><h2>角色记忆</h2><span class="caption">CHARACTER BIBLE</span></div><div class="memory-list">${m.characters.map(c=>`<div class="memory-item"><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p><p>声音设定：${esc(c.voice||'未指定')}</p></div>`).join('')||'<p class="muted">剧本生成后将建立角色记忆。</p>'}<div class="memory-item"><h3>全局视觉风格</h3><p>${esc(m.style)} · ${esc(current().brief.ratio)} · 保持身份、服装与道具连续性</p></div></div><div class="panel mt"><h3>故事事实</h3>${m.facts.map(f=>`<p class="result-note">${esc(f)}</p>`).join('')||'<p class="result-note">等待编剧产物。</p>'}<h3>任务摘要记忆</h3>${m.summaries.map(s=>`<div class="asset-row"><span class="badge">${esc(s.node)}</span><p>${esc(s.summary)}</p></div>`).join('')}</div><p class="footnote">${icon('info')}当前使用结构化项目记忆与检查点；尚未接入向量检索或跨项目长期记忆。</p>`;}
function assetsView(){const r=current();return `<div class="panel"><div class="panel-head"><div><h2>创作产物库</h2><p>每个阶段的输出，都可以独立检查与导出。</p></div></div>${[['script','file','结构化剧本','剧本场景、角色与对白','exportscript'],['storyboard','image','镜头脚本','景别、运镜、时长与生成提示词','exportboard'],['voice','mic','字幕与旁白','按镜头时间轴导出 SRT 字幕','exportsrt'],['compose','film',r.mode==='demo'?'动态分镜预览':'完整视听成片',r.mode==='demo'?'浏览器交互演示，非生成视频文件':'模型影像与配音经媒体工具合成','preview']].map(([id,i,title,desc,action])=>`<div class="asset-row"><span class="flow-icon">${icon(i)}</span><div><strong>${title}</strong><p>${desc}</p></div><button class="btn sm" ${r.artifacts[id]?'':'disabled'} ${action==='preview'?'data-view':'data-action'}="${action}">${icon(action==='preview'?'play':'download')}${r.artifacts[id]?(action==='preview'?'打开':'导出'):'未生成'}</button></div>`).join('')}</div><div class="panel"><h3>视觉素材来源</h3><p class="result-note">雨夜便利店：为本项目生成的 AI 概念图。演示镜头通过同一图像裁切与缩放呈现。自定义项目也使用此演示图，不代表依据用户简报生成。</p><a class="btn sm" href="assets/rain-store.webp" download="FrameFlow-概念图.webp">${icon('download')}下载概念图</a></div>`;}
function projectsView(){return `<div class="sectiontitle"><h2>所有短剧 <span class="muted small">/ ${projects.length}</span></h2><button class="btn primary sm" data-action="new">${icon('plus')}新建项目</button></div><div class="project-collection">${projects.map(p=>`<button class="projecttile" data-project="${p.id}"><img src="assets/rain-store.webp" alt="演示项目概念图"><div class="tilebody"><h3>${esc(p.brief.title)}</h3><p>${esc(p.brief.genre)} · ${p.brief.duration}s · ${p.mode==='demo'?'演示':'真实接口'} · ${states[p.status]}</p></div></button>`).join('')}</div>`;}
function logsView(){return `<div class="sectiontitle"><h2>可追溯执行记录</h2><button class="btn sm" data-action="export">${icon('download')}导出记录</button></div><div class="logs-full">${current().events.map(e=>`<div class="event"><time>${new Date(e.time).toLocaleTimeString('zh-CN')}</time><code>${esc(e.tool||e.type)}</code><p>${esc(e.message)}</p></div>`).join('')||'<p class="muted">暂无记录，运行工作流后可在这里查看。</p>'}</div>`;}
function openModal(title,sub,body){modal.innerHTML=`<div class="modal-head"><div><h2>${title}</h2><p>${sub}</p></div><button class="iconbtn" data-action="close" aria-label="关闭">${icon('close')}</button></div>${body}`;modal.showModal();}
function briefModal(edit=false){const b=edit?current().brief:{...DEFAULT_BRIEF,title:'',idea:''};openModal(edit?'编辑创作简报':'创建你的下一部短剧','用一个想法，开启一次完整的创作。',`<form id="brief-form"><div class="form-field"><label for="title">项目名称</label><input id="title" name="title" required maxlength="30" placeholder="为故事起一个名字" value="${esc(b.title)}"></div><div class="form-field"><label for="idea">故事创意</label><textarea id="idea" name="idea" required maxlength="4000" placeholder="人物是谁？发生了什么？你希望观众感受到什么？">${esc(b.idea)}</textarea></div><div class="form-grid"><div class="form-field"><label for="genre">故事类型</label><select id="genre" name="genre">${['都市奇幻','悬疑推理','浪漫爱情','治愈日常','科幻冒险'].map(x=>`<option ${b.genre===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label for="style">视觉风格</label><select id="style" name="style">${['电影写实','日系动画','复古胶片','水彩插画'].map(x=>`<option ${b.style===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label for="duration">目标时长</label><select id="duration" name="duration">${[30,60,90].map(x=>`<option value="${x}" ${Number(b.duration)===x?'selected':''}>${x} 秒</option>`).join('')}</select></div><div class="form-field"><label for="ratio">画面比例</label><select id="ratio" name="ratio"><option ${b.ratio==='16:9'?'selected':''}>16:9</option><option ${b.ratio==='9:16'?'selected':''}>9:16</option></select></div></div><div class="form-field"><label for="reference">视觉参考图（可选）</label><div class="ref-input"><input id="reference" type="file" accept="image/jpeg,image/png,image/webp"><small>真实模式会将图片交给支持视觉的模型，最大 2 MB。</small></div>${b.reference?'<span class="muted small">已保留当前参考图；选择新文件可替换。</span>':''}</div><label class="check-field"><input type="checkbox" name="manualReview" ${b.manualReview?'checked':''}><span>生成视频前，人工确认分镜<br><span class="muted small">确认画面与提示词后再继续调用后续工具</span></span></label><div class="modal-actions"><button type="button" class="btn" data-action="close">取消</button><button type="submit" class="btn primary">${edit?'保存简报':'创建项目'}</button></div></form>`);document.querySelector('#brief-form').onsubmit=async e=>{e.preventDefault();if(active()){toast('请先停止当前任务');return;}const form=e.target,fd=new FormData(form);let reference=b.reference||'';const file=document.querySelector('#reference').files[0];if(file){if(file.size>2*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('请选择 2 MB 以内的 JPG、PNG 或 WebP 图片');return;}reference=await new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.readAsDataURL(file);});}const brief={title:fd.get('title').trim(),idea:fd.get('idea').trim(),genre:fd.get('genre'),style:fd.get('style'),duration:Number(fd.get('duration')),ratio:fd.get('ratio'),manualReview:fd.has('manualReview'),reference};if(!brief.title||!brief.idea){toast('请填写项目名称与故事创意');return;}const n=createRun(brief,settings.mode);if(edit)projects[projects.findIndex(p=>p.id===currentId)]=n;else projects.unshift(n);currentId=n.id;modal.close();view='overview';stopPlayer();save();render();toast(edit?'已保存简报，后续产物将重新生成':'项目已创建，可以开始运行');};}
function settingsModal(){
  openModal('接入自己的 API','公开网页无需登录，真实生成使用你自己的模型服务。',connectionForm({settings,config:browserConfig,esc,icon,busy:active()}));
  bindConnectionForm({config:browserConfig,toast,onClear:()=>{for(const key of ['LLM_API_KEY','VIDEO_API_KEY','TTS_API_KEY'])browserConfig[key]='';},onSave:(nextSettings,nextConfig,savedConfig)=>{
    if(active())return;settings=nextSettings;browserConfig=nextConfig;
    try{localStorage.setItem('frameflow-settings',JSON.stringify(settings));localStorage.setItem('frameflow-api-config',JSON.stringify(savedConfig));}catch{toast('浏览器未允许存储，配置仅在当前页使用');}
    modal.close();render();toast('配置已应用，API Key 仅保留在当前标签页');
  }});
}
function docsModal(){openModal('AI 短剧 Agent 设计与编排','完整项目展示 · 实现边界与运行说明',`<div class="document"><div class="modal-section">FrameFlow 将创作拆分为 7 个专职 Agent，用显式依赖图和统一工具协议串联「剧本生成 → 分镜脚本 → 视频生成 → 配音合成」。</div><h3>任务规划与协作</h3><p>制片 Agent 生成任务计划；编剧建立角色事实；独立审稿后由导演拆解镜头。人工审批通过后，影像和声音任务并行执行，剪辑任务等待两个分支完成。</p><h3>工具与记忆</h3><p>网页直连模式使用你自己的 API，浏览器分别调用 LLM / MLLM、视频任务服务与 TTS，再通过浏览器媒体工具合成。个人服务端模式使用相同编排协议与 FFmpeg。角色、风格、故事事实与任务摘要随上下文传递。检查点支持停止、失败重试和服务重启后恢复。</p><h3>可直接体验的功能</h3><ul><li>新建项目与简报编辑、模型模式设置</li><li>真实运行的依赖调度、并发与重试机制</li><li>剧本 JSON 编辑、镜头提示词编辑、人工确认</li><li>项目记忆、工具调用日志与多项目本地保存</li><li>动态分镜播放、系统朗读、剧本与字幕导出</li></ul><h3>展示模式的明确边界</h3><p>演示剧本来自规则模板，任意创意不代表由 LLM 实时创作；展示图为本项目生成的单张 AI 概念图；各镜头使用同图裁切；语音为浏览器朗读；没有伪造模型调用、性能指标或成片视频。真实效果需要配置服务后验证。</p><h3>开源项目</h3><p>以 MIT 许可证公开源码，欢迎查看实现、提交建议与参与开发。<a href="https://github.com/WanyueZhang-ai/frameflow-ai-drama" target="_blank" rel="noopener noreferrer">在 GitHub 查看 FrameFlow</a></p><h3>本地启动</h3><div class="modal-section"><code>cp .env.example .env</code><br><code>npm start</code><br>打开 http://127.0.0.1:8787/studio.html，选择个人服务端。</div><p>项目源码包含配置示例、接口协议、编排测试与答辩展示路线。它是可演示的工程原型；生产部署还需要账户隔离、队列与对象存储。</p></div><div class="modal-actions"><button class="btn primary" data-action="close">开始体验</button></div>`);}
function invalidate(ids){const r=current();for(const id of ids){r.nodes[id]={status:'pending',attempts:0};delete r.artifacts[id];}r.memory.summaries=r.memory.summaries.filter(s=>!ids.includes(s.node));r.status='idle';r.approved=false;r.isSample=false;r.updatedAt=new Date().toISOString();r.events.push({time:r.updatedAt,type:'edit',node:null,message:'产物已编辑，相关下游任务与审批已重置'});}
function scriptModal(){const r=current();openModal('编辑结构化剧本','保留字段结构，保存后会重新生成审稿与后续产物。',`<div class="form-field"><label for="script-json">剧本 JSON</label><textarea id="script-json" class="editor" spellcheck="false">${esc(JSON.stringify(r.artifacts.script,null,2))}</textarea></div><div class="modal-actions"><button class="btn" data-action="close">取消</button><button class="btn primary" id="save-script">保存剧本</button></div>`);document.querySelector('#save-script').onclick=()=>{if(active())return;try{const a=JSON.parse(document.querySelector('#script-json').value);validateArtifact('script',a);r.artifacts.script=a;r.memory.characters=clone(a.characters);r.memory.facts=[a.logline,...a.scenes.map(s=>s.beat)];invalidate(['review','storyboard','video','voice','compose']);r.remoteId=null;save();modal.close();render();toast('剧本已保存，继续运行将从审稿阶段开始');}catch(e){toast(`无法保存：${e.message}`);}};}
function shotModal(index){const r=current(),s=r.artifacts.storyboard.shots[index];openModal(`镜头 ${String(index+1).padStart(2,'0')}`,'视觉提示词会继承角色记忆，并传递到视频生成工具。',`<div class="modal-section">${esc(s.camera)} · ${s.duration.toFixed(1)} 秒 · ${esc(s.sceneId)}</div><div class="form-field"><label for="shot-visual">画面描述</label><textarea id="shot-visual">${esc(s.visual)}</textarea></div><div class="form-field"><label for="shot-prompt">视频生成提示词</label><textarea id="shot-prompt">${esc(s.prompt)}</textarea></div><div class="form-field"><label for="shot-narration">旁白 / 对白</label><input id="shot-narration" value="${esc(s.narration)}"></div><div class="modal-actions"><button class="btn" data-action="close">关闭</button><button class="btn primary" id="save-shot" ${active()?'disabled':''}>保存镜头</button></div>`);document.querySelector('#save-shot').onclick=()=>{if(active())return;const visual=document.querySelector('#shot-visual').value.trim(),prompt=document.querySelector('#shot-prompt').value.trim(),narration=document.querySelector('#shot-narration').value.trim();if(!visual||!prompt||!narration)return toast('请填写所有镜头字段');Object.assign(s,{visual,prompt,narration});invalidate(['video','voice','compose']);r.remoteId=null;save();modal.close();render();toast('镜头已更新，下游产物已重置');};}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function safeMedia(s){if(browserMediaURLs.has(s))return s;if(typeof s==='string'&&/^https?:\/\//.test(s))return s;if(typeof s==='string'&&s.startsWith('/media/'))return settings.endpoint+s;return '';}
function srt(){let start=0;const fmt=n=>{const m=Math.round(n*1000);return `${String(Math.floor(m/3600000)).padStart(2,'0')}:${String(Math.floor(m/60000)%60).padStart(2,'0')}:${String(Math.floor(m/1000)%60).padStart(2,'0')},${String(m%1000).padStart(3,'0')}`;};return current().artifacts.storyboard.shots.map((s,i)=>{const line=`${i+1}\n${fmt(start)} --> ${fmt(start+s.duration)}\n${s.narration}\n`;start+=s.duration;return line;}).join('\n');}
function stopPlayer(){playing=false;clearInterval(playTimer);playTimer=null;if('speechSynthesis'in window)window.speechSynthesis.cancel();}
function shotAt(time){let acc=0;const shots=totals().shots;for(let i=0;i<shots.length;i++){acc+=shots[i].duration;if(time<acc)return i;}return shots.length-1;}
function updatePlayer(){if(view!=='preview'||!document.querySelector('#player'))return;const t=totals(),i=shotAt(playTime),shot=t.shots[i];if(!shot)return;const player=document.querySelector('#player');player.classList.toggle('playing',playing);document.querySelector('#subtitle').textContent=shot.narration;document.querySelector('#player-image').style.objectPosition=`${[50,80,85,60,90,50][i%6]}% center`;document.querySelector('#centerplay').style.display=playing?'none':'grid';document.querySelector('#playbutton').innerHTML=icon(playing?'pause':'play');document.querySelector('#seek').value=playTime;const fmt=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(Math.floor(n%60)).padStart(2,'0')}`;document.querySelector('#playtime').textContent=`${fmt(playTime)} / ${fmt(t.duration)}`;document.querySelectorAll('[data-seek]').forEach((el,n)=>el.classList.toggle('active',n===i));if(playing&&i!==lastShot&&narrationOn&&'speechSynthesis'in window){window.speechSynthesis.cancel();const speech=new SpeechSynthesisUtterance(shot.narration);speech.lang='zh-CN';speech.rate=.9;window.speechSynthesis.speak(speech);}lastShot=i;}
function togglePlay(){if(current().mode==='live')return;if(playing){stopPlayer();updatePlayer();return;}if(playTime>=totals().duration)playTime=0;playing=true;lastShot=-1;updatePlayer();let last=performance.now();playTimer=setInterval(()=>{const now=performance.now();playTime+=(now-last)/1000;last=now;if(playTime>=totals().duration){playTime=totals().duration;stopPlayer();}updatePlayer();},100);}
async function api(path,body,endpoint=settings.endpoint){const res=await fetch(`${endpoint}${path}`,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(12000)});if(!res.ok)throw new Error((await res.json().catch(()=>({}))).error||`服务端返回 ${res.status}`);if(!(res.headers.get('content-type')||'').includes('application/json'))throw new Error('当前在线站仅支持演示，请启动项目内的本地服务端');return res.json();}
function replaceRun(next){const i=projects.findIndex(p=>p.id===currentId);if(i<0)return;projects[i]=next;save();render();}
async function pollRemote(){clearTimeout(remoteTimer);const id=currentId,remote=current().remoteId;if(!remote)return;try{const next=await api(`/api/runs/${remote}`);if(currentId!==id)return;replaceRun({...next,id,remoteId:remote});if(next.status==='running')remoteTimer=setTimeout(pollRemote,900);}catch(e){toast(`执行记录连接中断：${e.message}。点击继续执行可重新连接。`);const r=current();r.status='cancelled';save();render();}}
async function runWorkflow(approve=false){if(active())return;if(engine?.busy){toast('另一个项目仍在运行，请等待完成');return;}stopPlayer();playTime=0;let r=current();if(r.status==='completed'||r.mode!==settings.mode){const n=createRun(r.brief,settings.mode);projects[projects.findIndex(p=>p.id===currentId)]=n;currentId=n.id;r=n;}r.isSample=false;save();if(r.mode==='live'){try{if(!r.remoteId){const next=await api('/api/runs',{run:r});r.remoteId=next.id;save();}await api(`/api/runs/${r.remoteId}/start`,{approve});await pollRemote();}catch(e){toast(e.message);render();}return;}const id=currentId;let tools;if(r.mode==='browser'){try{validateBrowserConfig(browserConfig);await prepareMedia();tools=createBrowserTools(browserConfig,{saveBlob:blob=>{const url=URL.createObjectURL(blob);browserMediaURLs.add(url);return url;}});}catch(error){toast(error.message);settingsModal();return;}}else tools=demoTools();engine=new Engine(r,tools,next=>{const idx=projects.findIndex(p=>p.id===id);if(idx<0)return;projects[idx]=next;save();if(currentId===id)render();});await engine.start({approve});}
const actions={new:()=>briefModal(),editbrief:()=>briefModal(true),settings:settingsModal,docs:docsModal,close:()=>modal.close(),projects:()=>{view='projects';render();},menu:()=>openModal('工作空间','选择工作区',`<div class="memory-list">${[['overview','创作工作台'],['projects','我的项目'],['assets','素材与产物'],['agents','Agent 编排'],['memory','项目记忆']].map(([v,n])=>`<button class="btn" data-view="${v}">${n}</button>`).join('')}<button class="btn" data-action="new">新建项目</button></div>`),run:()=>runWorkflow(),approve:()=>runWorkflow(true),stop:async()=>{if(current().mode==='live'){try{await api(`/api/runs/${current().remoteId}/stop`,{});await pollRemote();}catch(e){toast(e.message);}}else engine?.stop();},export:()=>download(`${current().brief.title}-项目.json`,JSON.stringify({schemaVersion:1,source:SOURCE,project:current()},null,2)),exportboard:()=>{if(!current().artifacts.storyboard)return toast('请先生成分镜');download(`${current().brief.title}-分镜.json`,JSON.stringify(current().artifacts.storyboard,null,2));},exportscript:()=>{const a=current().artifacts.script;if(!a)return toast('请先生成剧本');download(`${a.title}-剧本.txt`,`${a.title}\n\n${a.logline}\n\n${a.scenes.map(s=>`${s.location}\n${s.beat}\n\n${s.dialogue.map(d=>`${d.speaker}：${d.text}`).join('\n')}`).join('\n\n')}`,'text/plain;charset=utf-8');},exportsrt:()=>{if(!current().artifacts.storyboard)return toast('请先生成分镜');download(`${current().brief.title}.srt`,srt(),'text/plain;charset=utf-8');},editscript:scriptModal,play:togglePlay,narration:()=>{if(!('speechSynthesis'in window))return toast('当前浏览器不支持系统朗读');narrationOn=!narrationOn;document.querySelector('#voice-label').textContent=narrationOn?'朗读已开':'开启朗读';lastShot=-1;if(!narrationOn)window.speechSynthesis.cancel();updatePlayer();},connection:async()=>{const el=document.querySelector('#connection-result');el.textContent='正在检查…';try{const x=await api('/api/health',undefined,document.querySelector('#endpoint').value.trim().replace(/\/$/,''));el.textContent=`已连接 · LLM ${x.llm?'已配置':'未配置'} / TTS ${x.tts?'已配置':'未配置'} / 视频 ${x.video?'已配置':'未配置'} / 合成 ${x.compose?'已配置':'未配置'}`;}catch(e){el.textContent=e.message;}},downloadvideo:()=>{const artifact=current().artifacts.compose,url=safeMedia(artifact?.url);if(!url)return;if(browserMediaURLs.has(url)){const a=document.createElement('a');a.href=url;a.download=`${current().brief.title}.${artifact.format.startsWith('MP4')?'mp4':'webm'}`;a.click();}else window.open(url,'_blank','noopener');}};
document.addEventListener('click',e=>{const button=e.target.closest('[data-action],[data-view],[data-project],[data-shot],[data-seek]');if(!button||button.disabled)return;if(button.dataset.view){stopPlayer();view=button.dataset.view;modal.close();render();window.scrollTo({top:0});}else if(button.dataset.project){stopPlayer();clearTimeout(remoteTimer);currentId=button.dataset.project;view='overview';playTime=0;save();render();if(location.hash==='#connect')settingsModal();if(current().mode==='live'&&current().status==='running')pollRemote();}else if(button.dataset.shot!==undefined)shotModal(Number(button.dataset.shot));else if(button.dataset.seek!==undefined){const wasPlaying=playing;stopPlayer();playTime=totals().shots.slice(0,Number(button.dataset.seek)).reduce((n,s)=>n+s.duration,0);lastShot=-1;if(wasPlaying)togglePlay();else updatePlayer();}else actions[button.dataset.action]?.();});
document.addEventListener('input',e=>{if(e.target.id==='seek'){const wasPlaying=playing;stopPlayer();playTime=Number(e.target.value);lastShot=-1;if(wasPlaying)togglePlay();else updatePlayer();}});
modal.addEventListener('click',e=>{if(e.target===modal){const b=modal.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)modal.close();}});
window.addEventListener('beforeunload',()=>{stopPlayer();save();});
save();render();if(location.hash==='#connect')settingsModal();if(current().mode==='live'&&current().status==='running')pollRemote();
